//! A34 complete ordered decision-panel carrier (compact domain 87).
//!
//! Rows must come from the receipt-bound materializer/insertion/text/alert TLS
//! bracket. The renderer never evaluates Clausewitz scripts or reconstructs
//! order from authored definitions.

pub mod a729_hook;
use std::collections::BTreeSet;

pub const DOMAIN_ID:u16=87; pub const DOMAIN_NAME:&str="decision_panel_live"; pub const MAGIC:u32=u32::from_le_bytes(*b"DPN1"); pub const SCHEMA_VERSION:u32=1;
pub const EXECUTABLE_SHA256:[u8;32]=hex32(b"870ebf1f615262facca48a3b947775c41f0a5338f3068c40958209f5c41c65ad");
pub const EXACT20_FUNCTION_MANIFEST_SHA256:[u8;32]=hex32(b"2341981c14983a46bafe8c1be0fa69272a9eb9a33c58d4c8ddef2bd1617a1a8e");
pub const EXACT20_DATA_ARTIFACT_SHA256:[u8;32]=hex32(b"a5b06165bef6b8cc92d22595633ac8c778f539cf98f1f84f3dec576b8f307a24");
pub const PRODUCTION_SCHEDULING_ENABLED:bool=false; pub const LIVE_FIXTURE_ACCEPTED:bool=false; pub const MAX_ROWS:usize=32_768; pub const MAX_TEXT_BYTES:usize=16_384;
const fn hex32(input:&[u8;64])->[u8;32]{const fn n(v:u8)->u8{match v{b'0'..=b'9'=>v-b'0',b'a'..=b'f'=>v-b'a'+10,b'A'..=b'F'=>v-b'A'+10,_=>0xff}}let mut o=[0;32];let mut i=0;while i<32{o[i]=(n(input[i*2])<<4)|n(input[i*2+1]);i+=1}o}

#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum AuthorityState{Unavailable,Exact20Receipt}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Availability{Available,Unavailable,Active,OnCooldown}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum Lifecycle{Pending,Running,Completed,Failed,Removed}
#[derive(Clone,Debug,PartialEq,Eq,PartialOrd,Ord)]pub enum Target{Country(String),State(u32)}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct Cost{pub political_power:Option<i64>,pub custom_cost_available:Option<bool>,pub formatted_text:Option<String>}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct DecisionRow{pub decision_id:String,pub category_id:String,pub presentation_index:u32,pub availability:Availability,pub lifecycle:Lifecycle,pub target:Option<Target>,pub cost:Option<Cost>,pub remaining_timer_days:Option<i32>,pub cooldown_remaining_days:Option<i32>,pub name_text:String,pub timer_text:Option<String>,pub alert_to_take:bool,pub alert_timeout:bool}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct DecisionPanelSnapshot{pub source_sequence:u64,pub producer_complete:bool,pub country_tag:String,pub available_alert_count:u32,pub timeout_alert_count:u32,pub rows:Vec<DecisionRow>}
#[derive(Clone,Debug,PartialEq,Eq)]pub struct DecisionPanelFrame{pub elapsed_wall_ms:u64,pub frame_hour:u64,pub status_flags:u32,pub authority:AuthorityState,pub snapshot:Option<DecisionPanelSnapshot>}
pub trait ExactDecisionPanelSource{fn is_exact_a729_materializer_source(&self)->bool;fn read_decision_panel(&self,frame_hour:u64)->Result<DecisionPanelSnapshot,String>;}
#[derive(Clone,Debug,PartialEq,Eq)]pub enum CarrierError{ActivationDisabled,Source(String),Invalid(String),Truncated,TrailingBytes}
fn invalid<T>(m:impl Into<String>)->Result<T,CarrierError>{Err(CarrierError::Invalid(m.into()))}
fn text_ok(v:&str,required:bool)->bool{v.len()<=MAX_TEXT_BYTES&&(!required||!v.is_empty())&&!v.as_bytes().contains(&0)}

pub fn validate_snapshot(s:&DecisionPanelSnapshot)->Result<(),CarrierError>{if s.source_sequence==0||!s.producer_complete||!text_ok(&s.country_tag,true)||s.rows.len()>MAX_ROWS{return invalid("DPN1 snapshot incomplete")};let mut ids=BTreeSet::new();let mut take=0u32;let mut timeout=0u32;for(i,r)in s.rows.iter().enumerate(){if r.presentation_index as usize!=i||!text_ok(&r.decision_id,true)||!text_ok(&r.category_id,true)||!text_ok(&r.name_text,true)||r.timer_text.as_deref().is_some_and(|v|!text_ok(v,true))||r.remaining_timer_days.is_some_and(|v|v<0)||r.cooldown_remaining_days.is_some_and(|v|v<0){return invalid("DPN1 row order/text/timer invalid")};if !ids.insert((r.decision_id.clone(),r.target.clone())){return invalid("DPN1 duplicate decision target")};match &r.target{Some(Target::Country(v))if text_ok(v,true)=>{},Some(Target::State(v))if *v>0=>{},Some(_)=>return invalid("DPN1 target invalid"),None=>{}}if let Some(c)=&r.cost{if c.formatted_text.as_deref().is_some_and(|v|!text_ok(v,true)){return invalid("DPN1 cost text invalid")}}if r.remaining_timer_days.is_some()||r.cooldown_remaining_days.is_some(){if r.timer_text.is_none(){return invalid("DPN1 timer value lacks exact text")}}else if r.timer_text.is_some(){return invalid("DPN1 timer text lacks exact value")};if r.alert_to_take{take=take.checked_add(1).ok_or_else(||CarrierError::Invalid("DPN1 alert count overflow".into()))?}if r.alert_timeout{timeout=timeout.checked_add(1).ok_or_else(||CarrierError::Invalid("DPN1 alert count overflow".into()))?}}if take!=s.available_alert_count||timeout!=s.timeout_alert_count{return invalid("DPN1 alert membership/count mismatch")};Ok(())}
pub fn validate_frame(f:&DecisionPanelFrame)->Result<(),CarrierError>{match f.authority{AuthorityState::Unavailable if f.status_flags!=0&&f.snapshot.is_none()=>Ok(()),AuthorityState::Exact20Receipt if f.status_flags==0&&f.snapshot.is_some()=>validate_snapshot(f.snapshot.as_ref().unwrap()),_=>invalid("DPN1 authority/availability mismatch")}}
pub fn collect_and_encode<S:ExactDecisionPanelSource>(source:&S,frame_hour:u64,elapsed_wall_ms:u64)->Result<Vec<u8>,CarrierError>{if !PRODUCTION_SCHEDULING_ENABLED||!LIVE_FIXTURE_ACCEPTED{return Err(CarrierError::ActivationDisabled)}if !source.is_exact_a729_materializer_source(){return Err(CarrierError::Source("source is not the receipt-bound materializer TLS bracket".into()))}let snapshot=source.read_decision_panel(frame_hour).map_err(CarrierError::Source)?;encode_payload(&DecisionPanelFrame{elapsed_wall_ms,frame_hour,status_flags:0,authority:AuthorityState::Exact20Receipt,snapshot:Some(snapshot)})}
pub fn encode_unavailable(frame_hour:u64,elapsed_wall_ms:u64,status_flags:u32)->Result<Vec<u8>,CarrierError>{encode_payload(&DecisionPanelFrame{elapsed_wall_ms,frame_hour,status_flags,authority:AuthorityState::Unavailable,snapshot:None})}

pub fn encode_payload(f:&DecisionPanelFrame)->Result<Vec<u8>,CarrierError>{validate_frame(f)?;let mut o=Vec::new();u32v(&mut o,MAGIC);u32v(&mut o,SCHEMA_VERSION);u32v(&mut o,match f.authority{AuthorityState::Unavailable=>0,AuthorityState::Exact20Receipt=>1});u32v(&mut o,f.status_flags);u64v(&mut o,f.elapsed_wall_ms);u64v(&mut o,f.frame_hour);o.extend_from_slice(&EXECUTABLE_SHA256);o.extend_from_slice(&EXACT20_FUNCTION_MANIFEST_SHA256);o.extend_from_slice(&EXACT20_DATA_ARTIFACT_SHA256);o.push(u8::from(f.snapshot.is_some()));o.extend_from_slice(&[0;3]);if let Some(s)=&f.snapshot{u64v(&mut o,s.source_sequence);textv(&mut o,&s.country_tag);u32v(&mut o,s.available_alert_count);u32v(&mut o,s.timeout_alert_count);u32v(&mut o,s.rows.len() as u32);for r in &s.rows{u32v(&mut o,r.presentation_index);o.push(av_raw(r.availability));o.push(life_raw(r.lifecycle));o.push(match &r.target{None=>0,Some(Target::Country(_))=>1,Some(Target::State(_))=>2});let mut flags=0u16;if r.cost.is_some(){flags|=1}if r.cost.as_ref().and_then(|c|c.political_power).is_some(){flags|=2}if r.cost.as_ref().and_then(|c|c.custom_cost_available).is_some(){flags|=4}if r.cost.as_ref().and_then(|c|c.custom_cost_available)==Some(true){flags|=8}if r.cost.as_ref().and_then(|c|c.formatted_text.as_ref()).is_some(){flags|=16}if r.remaining_timer_days.is_some(){flags|=32}if r.cooldown_remaining_days.is_some(){flags|=64}if r.timer_text.is_some(){flags|=128}if r.alert_to_take{flags|=256}if r.alert_timeout{flags|=512}u16v(&mut o,flags);i32v(&mut o,r.remaining_timer_days.unwrap_or(-1));i32v(&mut o,r.cooldown_remaining_days.unwrap_or(-1));i64v(&mut o,r.cost.as_ref().and_then(|c|c.political_power).unwrap_or(0));match &r.target{Some(Target::State(v))=>u32v(&mut o,*v),_=>u32v(&mut o,0)}textv(&mut o,&r.decision_id);textv(&mut o,&r.category_id);textv(&mut o,match &r.target{Some(Target::Country(v))=>v.as_str(),_=>""});textv(&mut o,&r.name_text);opt_textv(&mut o,r.timer_text.as_deref());opt_textv(&mut o,r.cost.as_ref().and_then(|c|c.formatted_text.as_deref()));}}Ok(o)}

pub fn decode_payload(p:&[u8])->Result<DecisionPanelFrame,CarrierError>{let mut r=Reader{p,at:0};if r.u32()?!=MAGIC||r.u32()?!=SCHEMA_VERSION{return invalid("DPN1 magic/schema mismatch")};let authority=match r.u32()?{0=>AuthorityState::Unavailable,1=>AuthorityState::Exact20Receipt,_=>return invalid("DPN1 authority unknown")};let status_flags=r.u32()?;let elapsed_wall_ms=r.u64()?;let frame_hour=r.u64()?;if r.bytes(32)?!=EXECUTABLE_SHA256||r.bytes(32)?!=EXACT20_FUNCTION_MANIFEST_SHA256||r.bytes(32)?!=EXACT20_DATA_ARTIFACT_SHA256{return invalid("DPN1 receipt identity mismatch")};let has=r.u8()?;if has>1||r.bytes(3)?!=[0,0,0]{return invalid("DPN1 availability invalid")};let snapshot=if has==1{let source_sequence=r.u64()?;let country_tag=r.text()?;let available_alert_count=r.u32()?;let timeout_alert_count=r.u32()?;let n=r.u32()? as usize;if n>MAX_ROWS{return invalid("DPN1 row count exceeds bound")};let mut rows=Vec::with_capacity(n);for _ in 0..n{let presentation_index=r.u32()?;let availability=av_from(r.u8()?)?;let lifecycle=life_from(r.u8()?)?;let tk=r.u8()?;let flags=r.u16()?;if flags&!0x3ff!=0{return invalid("DPN1 row flags unknown")};let remaining=opt_nonnegative(r.i32()?,flags&32!=0)?;let cooldown=opt_nonnegative(r.i32()?,flags&64!=0)?;let pp=r.i64()?;let state_id=r.u32()?;let decision_id=r.text()?;let category_id=r.text()?;let target_country=r.text()?;let name_text=r.text()?;let timer_text=r.opt_text()?;let cost_text=r.opt_text()?;let target=match tk{0 if state_id==0&&target_country.is_empty()=>None,1 if state_id==0&&!target_country.is_empty()=>Some(Target::Country(target_country)),2 if state_id>0&&target_country.is_empty()=>Some(Target::State(state_id)),_=>return invalid("DPN1 target encoding invalid")};let cost=if flags&1!=0{Some(Cost{political_power:(flags&2!=0).then_some(pp),custom_cost_available:if flags&4!=0{Some(flags&8!=0)}else{None},formatted_text:cost_text})}else{if flags&(2|4|8|16)!=0||cost_text.is_some(){return invalid("DPN1 absent cost has fields")};None};if (flags&128!=0)!=timer_text.is_some()||(flags&16!=0)!=cost.as_ref().and_then(|c|c.formatted_text.as_ref()).is_some(){return invalid("DPN1 optional text flags mismatch")};rows.push(DecisionRow{decision_id,category_id,presentation_index,availability,lifecycle,target,cost,remaining_timer_days:remaining,cooldown_remaining_days:cooldown,name_text,timer_text,alert_to_take:flags&256!=0,alert_timeout:flags&512!=0});}Some(DecisionPanelSnapshot{source_sequence,producer_complete:true,country_tag,available_alert_count,timeout_alert_count,rows})}else{None};if r.at!=p.len(){return Err(CarrierError::TrailingBytes)}let f=DecisionPanelFrame{elapsed_wall_ms,frame_hour,status_flags,authority,snapshot};validate_frame(&f)?;Ok(f)}

fn av_raw(v:Availability)->u8{match v{Availability::Available=>0,Availability::Unavailable=>1,Availability::Active=>2,Availability::OnCooldown=>3}}fn av_from(v:u8)->Result<Availability,CarrierError>{match v{0=>Ok(Availability::Available),1=>Ok(Availability::Unavailable),2=>Ok(Availability::Active),3=>Ok(Availability::OnCooldown),_=>invalid("DPN1 availability enum unknown")}}fn life_raw(v:Lifecycle)->u8{match v{Lifecycle::Pending=>0,Lifecycle::Running=>1,Lifecycle::Completed=>2,Lifecycle::Failed=>3,Lifecycle::Removed=>4}}fn life_from(v:u8)->Result<Lifecycle,CarrierError>{match v{0=>Ok(Lifecycle::Pending),1=>Ok(Lifecycle::Running),2=>Ok(Lifecycle::Completed),3=>Ok(Lifecycle::Failed),4=>Ok(Lifecycle::Removed),_=>invalid("DPN1 lifecycle enum unknown")}}fn opt_nonnegative(v:i32,present:bool)->Result<Option<i32>,CarrierError>{if present&&v>=0{Ok(Some(v))}else if !present&&v==-1{Ok(None)}else{invalid("DPN1 optional timer encoding invalid")}}
fn u16v(o:&mut Vec<u8>,v:u16){o.extend_from_slice(&v.to_le_bytes())}fn u32v(o:&mut Vec<u8>,v:u32){o.extend_from_slice(&v.to_le_bytes())}fn i32v(o:&mut Vec<u8>,v:i32){o.extend_from_slice(&v.to_le_bytes())}fn u64v(o:&mut Vec<u8>,v:u64){o.extend_from_slice(&v.to_le_bytes())}fn i64v(o:&mut Vec<u8>,v:i64){o.extend_from_slice(&v.to_le_bytes())}fn textv(o:&mut Vec<u8>,v:&str){u32v(o,v.len() as u32);o.extend_from_slice(v.as_bytes())}fn opt_textv(o:&mut Vec<u8>,v:Option<&str>){match v{Some(v)=>{o.push(1);textv(o,v)},None=>o.push(0)}}
struct Reader<'a>{p:&'a[u8],at:usize}impl<'a>Reader<'a>{fn bytes(&mut self,n:usize)->Result<&'a[u8],CarrierError>{let e=self.at.checked_add(n).ok_or(CarrierError::Truncated)?;let b=self.p.get(self.at..e).ok_or(CarrierError::Truncated)?;self.at=e;Ok(b)}fn u8(&mut self)->Result<u8,CarrierError>{Ok(self.bytes(1)?[0])}fn u16(&mut self)->Result<u16,CarrierError>{Ok(u16::from_le_bytes(self.bytes(2)?.try_into().unwrap()))}fn u32(&mut self)->Result<u32,CarrierError>{Ok(u32::from_le_bytes(self.bytes(4)?.try_into().unwrap()))}fn i32(&mut self)->Result<i32,CarrierError>{Ok(i32::from_le_bytes(self.bytes(4)?.try_into().unwrap()))}fn u64(&mut self)->Result<u64,CarrierError>{Ok(u64::from_le_bytes(self.bytes(8)?.try_into().unwrap()))}fn i64(&mut self)->Result<i64,CarrierError>{Ok(i64::from_le_bytes(self.bytes(8)?.try_into().unwrap()))}fn text(&mut self)->Result<String,CarrierError>{let n=self.u32()? as usize;if n>MAX_TEXT_BYTES{return invalid("DPN1 text exceeds bound")};String::from_utf8(self.bytes(n)?.to_vec()).map_err(|_|CarrierError::Invalid("DPN1 text invalid UTF-8".into()))}fn opt_text(&mut self)->Result<Option<String>,CarrierError>{match self.u8()?{0=>Ok(None),1=>Ok(Some(self.text()?)),_=>invalid("DPN1 optional text marker invalid")}}}

#[cfg(test)]mod tests{use super::*;fn frame()->DecisionPanelFrame{DecisionPanelFrame{elapsed_wall_ms:1,frame_hour:55,status_flags:0,authority:AuthorityState::Exact20Receipt,snapshot:Some(DecisionPanelSnapshot{source_sequence:7,producer_complete:true,country_tag:"ENG".into(),available_alert_count:1,timeout_alert_count:0,rows:vec![DecisionRow{decision_id:"decision_one".into(),category_id:"category_one".into(),presentation_index:0,availability:Availability::Available,lifecycle:Lifecycle::Pending,target:None,cost:Some(Cost{political_power:Some(50),custom_cost_available:None,formatted_text:Some("50".into())}),remaining_timer_days:None,cooldown_remaining_days:None,name_text:"Exact decision".into(),timer_text:None,alert_to_take:true,alert_timeout:false}]})}}#[test]fn roundtrip_preserves_order_text_and_membership(){let f=frame();assert_eq!(decode_payload(&encode_payload(&f).unwrap()).unwrap(),f)}#[test]fn mismatched_alert_count_rejects_whole_panel(){let mut f=frame();f.snapshot.as_mut().unwrap().available_alert_count=0;assert!(encode_payload(&f).is_err())}#[test]fn production_source_remains_inert(){struct S;impl ExactDecisionPanelSource for S{fn is_exact_a729_materializer_source(&self)->bool{true}fn read_decision_panel(&self,_:u64)->Result<DecisionPanelSnapshot,String>{Ok(frame().snapshot.unwrap())}}assert_eq!(collect_and_encode(&S,55,0),Err(CarrierError::ActivationDisabled));}}
